    private function validateStoredItem(array $r,array $item): void{if(($item['evidence_policy_code']??'OPTIONAL')==='REQUIRED')throw new \RuntimeException('필수 증빙 휴가는 공용 첨부 기능 지원 전까지 상신할 수 없습니다.');if($this->model->monthClosed($r['employee_id'],$item['leave_date']))throw new \RuntimeException('근태 마감월에는 휴가를 처리할 수 없습니다.');if($this->model->overlappingUsage($r['employee_id'],$item['request_unit_code']==='HOURLY'?$item['requested_start_at']:$item['scheduled_start_at_snapshot'],$item['request_unit_code']==='HOURLY'?$item['requested_end_at']:$item['scheduled_end_at_snapshot'],$r['id']))throw new \RuntimeException('승인된 휴가와 사용구간이 중복됩니다.');}
    private function recalculateAttendance(string $employee,string $date,string $actor): void{(new AttendanceService($this->db))->recalculateApprovedLeave($employee,$date,$actor);}
    private function consumeGrants(string $employee,string $type,int $year,string $occurredOn,int $minutes,string $usageId,string $itemId,string $actor): void
    {
        $grants=$this->model->grantsForConsumption($employee,$type,$year,$occurredOn);
        $balances=$this->model->grantBalances(array_column($grants,'id'));
        $remaining=$minutes;$allocations=[];
        foreach($grants as$grant){$available=max(0,(int)($balances[$grant['id']]??0));if($available===0)continue;$amount=min($remaining,$available);$allocations[]=['grant_id'=>$grant['id'],'minutes'=>$amount];$remaining-=$amount;if($remaining===0)break;}
        if($remaining>0)throw new \RuntimeException('사용 가능한 휴가 Grant 잔액이 부족합니다.');
        foreach($allocations as$index=>$allocation){$sequence=$index+1;$this->ledger($employee,$type,$year,'USAGE',-$allocation['minutes'],'USAGE',$usageId,'승인된 휴가 사용','USAGE-'.$itemId.'-'.$sequence,$actor,$allocation['grant_id'],$sequence,$occurredOn);}
    }
    private function calculationBasis(mixed $value,string $source): ?string
    {
