        if(!is_array($decoded)||$decoded===[])throw new \InvalidArgumentException('계산확정 부여에는 계산 근거 JSON이 필요합니다.');
        foreach(['schema_version','calculation_date','calculation_period','employment_basis','attendance_basis','statutory_standard','policy_version','calculated_minutes']as$key)if(!array_key_exists($key,$decoded))throw new \InvalidArgumentException('계산확정 부여의 계산 근거 항목이 누락되었습니다.');
        if(!is_array($decoded['calculation_period'])||!is_array($decoded['employment_basis'])||!is_array($decoded['attendance_basis'])||!is_array($decoded['statutory_standard'])||(int)$decoded['calculated_minutes']<=0)throw new \InvalidArgumentException('계산확정 부여의 계산 근거 구조가 올바르지 않습니다.');
