    private function ledger(string $employee,string $type,int $year,string $entry,int $amount,string $domain,string $source,string $reason,string $key,string $actor,?string $grantId=null,int $sequence=1,?string $occurredOn=null): array{if($old=$this->model->ledgerByRequest($key))return$old;$row=['id'=>UuidHelper::generate(),'employee_id'=>$employee,'leave_type_id'=>$type,'grant_id'=>$grantId,'base_year'=>$year,'entry_type_code'=>$entry,'amount_minutes'=>$amount,'source_domain_code'=>$domain,'source_id'=>$source,'source_sequence'=>$sequence,'occurred_on'=>$occurredOn??date('Y-m-d'),'reason'=>$reason,'request_key'=>$key,'created_at'=>date('Y-m-d H:i:s'),'created_by'=>$actor];$this->model->insert('institution_leave_ledger_entries',$row);return$row;}
    private function audit(string $domain,string $target,string $employee,string $action,string $source,string $reason,string $key,?array $before,?array $after,?string $approval,string $actor): void{$this->model->insert('institution_leave_audits',['id'=>UuidHelper::generate(),'leave_domain'=>$domain,'target_id'=>$target,'employee_id'=>$employee,'action_type_code'=>$action,'source_type_code'=>$source,'reason'=>$reason,'approval_request_id'=>$approval,'request_key'=>$key,'before_data'=>$before?json_encode($before,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,'after_data'=>$after?json_encode($after,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,'processed_by'=>$actor,'processed_at'=>date('Y-m-d H:i:s')]);}
